use nomina_fiscal_package as n;
use n::limits::*;
use serde_json::{Value,json};
use base64::{Engine,engine::general_purpose::URL_SAFE_NO_PAD};
fn parse(s:&str)->n::errors::Result<Value>{n::strict_json::parse(s.as_bytes())}
fn hex(s:&str)->Vec<u8>{assert_eq!(s.len()%2,0);(0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap()).collect()}
#[test]fn file_limit_exact_and_plus_one(){let valid=format!("0{}"," ".repeat(MAX_BYTES-1));assert_eq!(parse(&valid).unwrap(),json!(0));assert_eq!(parse(&(valid+" ")).unwrap_err().code,"FILE_LIMIT");}
#[test]fn depth_limit_exact_and_plus_one(){let value=|n:usize|format!("{}null{}","[".repeat(n),"]".repeat(n));assert!(parse(&value(MAX_DEPTH)).is_ok());assert_eq!(parse(&value(MAX_DEPTH+1)).unwrap_err().code,"DEPTH_LIMIT");}
#[test]fn node_limit_exact_and_plus_one(){let mut chunks=vec![vec![Value::Null;1000];49];chunks.push(vec![Value::Null;949]);let v=serde_json::to_string(&chunks).unwrap();assert!(parse(&v).is_ok());chunks.last_mut().unwrap().push(Value::Null);assert_eq!(parse(&serde_json::to_string(&chunks).unwrap()).unwrap_err().code,"NODE_LIMIT");}
#[test]fn property_limit_exact_and_plus_one(){let object=|n|serde_json::to_string(&(0..n).map(|i|(format!("k{i:03}"),Value::Null)).collect::<serde_json::Map<_,_>>()).unwrap();assert!(parse(&object(MAX_PROPERTIES)).is_ok());assert_eq!(parse(&object(MAX_PROPERTIES+1)).unwrap_err().code,"PROPERTY_LIMIT");}
#[test]fn array_limit_exact_and_plus_one(){assert!(parse(&serde_json::to_string(&vec![0;MAX_ARRAY_ITEMS]).unwrap()).is_ok());assert_eq!(parse(&serde_json::to_string(&vec![0;MAX_ARRAY_ITEMS+1]).unwrap()).unwrap_err().code,"ARRAY_LIMIT");}
#[test]fn string_limit_exact_plus_one_and_escaped(){for length in [MAX_STRING_BYTES,MAX_STRING_BYTES+1]{let text=serde_json::to_string(&"a".repeat(length)).unwrap();assert_eq!(parse(&text).is_ok(),length==MAX_STRING_BYTES);}let escaped=format!("\"{}\"","\\u0061".repeat(MAX_STRING_BYTES));assert!(parse(&escaped).is_ok());assert!(parse(&format!("\"{}\"","é".repeat(MAX_STRING_BYTES/2))).is_ok());}
#[test]fn key_limit_exact_and_plus_one(){assert!(parse(&format!("{{\"{}\":null}}","k".repeat(MAX_KEY_BYTES))).is_ok());assert_eq!(parse(&format!("{{\"{}\":null}}","k".repeat(MAX_KEY_BYTES+1))).unwrap_err().code,"KEY_LIMIT");}
#[test]fn identifier_limit_exact_and_plus_one(){assert!(n::validation_2026::identifier(&"a".repeat(MAX_ID_BYTES)));assert!(!n::validation_2026::identifier(&"a".repeat(MAX_ID_BYTES+1)));assert!(!n::validation_2026::identifier("../module.js"));}
#[test]fn duplicates_decoded_keys_and_nested(){for value in [r#"{"a":1,"a":2}"#,r#"{"a":1,"\u0061":2}"#,r#"{"nested":[{"x":0,"x":0}]}"#]{assert_eq!(parse(value).unwrap_err().code,"DUPLICATE_KEY");}}
#[test]fn strict_numbers_before_floating_conversion(){for value in ["-0","-1","1.0","1e0","1E400","0.00000000000000000000001","9007199254740992","18446744073709551616","01","NaN","Infinity"]{assert!(parse(value).is_err(),"Unexpected number acceptance");}assert_eq!(parse("9007199254740991").unwrap(),json!(MAX_SAFE_INTEGER));}
#[test]fn malformed_utf8_bom_and_surrogates(){for b in [&[0xff][..],&[0xc0,0xaf][..],&[0xef,0xbb,0xbf,b'0'][..],&[b'"',0xed,0xa0,0x80,b'"'][..]]{assert!(n::strict_json::parse(b).is_err());}for value in [r#""\ud800""#,r#""\udfff""#]{assert!(parse(value).is_err());}assert_eq!(parse(r#""\ud83d\ude00""#).unwrap(),json!("😀"));}
#[test]fn trailing_data_comments_sparse_and_trailing_comma(){for value in ["0 1","{}/*comment*/","[1,]","[,,]","{\"a\":1,}","{\"a\":}","\"unterminated"]{assert!(parse(value).is_err());}}
#[test]fn jcs_six_independent_golden_vectors(){let vectors:Vec<Value>=serde_json::from_str(include_str!("vectors/jcs.json")).unwrap();assert_eq!(vectors.len(),6);for v in vectors{let input:Value=serde_json::from_str(v["input"].as_str().unwrap()).unwrap();assert_eq!(n::canonical::bytes(&input).unwrap(),v["output"].as_str().unwrap().as_bytes(),"JCS golden mismatch: {}",v["name"]);}}
#[test]fn jcs_rfc_number_samples_general_not_fiscal_parser(){for (bits,expected)in [(0x0000000000000000,"0"),(0x8000000000000000,"0"),(0x0000000000000001,"5e-324"),(0x7fefffffffffffff,"1.7976931348623157e+308"),(0x4340000000000000,"9007199254740992"),(0x44b52d02c7e14af6,"1e+23"),(0x3eb0c6f7a0b5ed8d,"0.000001"),(0x43143ff3c1cb0959,"1424953923781206.2")]{assert_eq!(n::canonical::bytes(&f64::from_bits(bits)).unwrap(),expected.as_bytes());}assert!(n::canonical::bytes(&f64::NAN).is_err());assert!(n::canonical::bytes(&f64::INFINITY).is_err());}
#[test]fn unicode_not_normalized_and_utf16_order(){let a=json!({"v":"A\u{030a}"});let b=json!({"v":"Å"});assert_ne!(n::canonical::bytes(&a).unwrap(),n::canonical::bytes(&b).unwrap());let v=json!({"\u{fb33}":1,"😀":2});assert_eq!(String::from_utf8(n::canonical::bytes(&v).unwrap()).unwrap(),"{\"😀\":2,\"דּ\":1}");}
#[test]fn actual_2026_bytes_equal_historical_canonicalization_and_sha(){let s:Value=serde_json::from_str(include_str!("../../../docs/evidence/5d3a/editorial-source-2026.json")).unwrap();let historical=include_bytes!("../../../docs/evidence/5d3a/legacy-registry.canonical.json");let canonical=n::canonical::bytes(&s["registry"]).unwrap();assert_eq!(canonical.as_slice(),historical.as_slice());assert_eq!(n::hashes::sha256(&canonical),"7e9f13084e64633b29959d79eec5f9c02333fe2695809c662d71fa7fc8393ab0");let typed: n::wire::SignedPackage=n::decode_closed(&s).unwrap();n::validation_2026::validate(&typed).unwrap();n::compatibility::CompiledPolicy::current_2026().guard(&typed).unwrap();}
#[test]fn ordinary_serde_output_is_not_claimed_jcs(){let v=json!({"\u{fb33}":1,"😀":2});assert_ne!(serde_json::to_vec(&v).unwrap(),n::canonical::bytes(&v).unwrap());}
#[test]fn all_published_rfc8032_vectors_no_private_seeds(){let vectors:Vec<Value>=serde_json::from_str(include_str!("vectors/rfc8032-public.json")).unwrap();assert_eq!(vectors.len(),3);for v in vectors{let p: [u8;32]=hex(v["public"].as_str().unwrap()).try_into().unwrap();let key=n::signature::public_key(&URL_SAFE_NO_PAD.encode(p),&n::hashes::key_id(&p)).unwrap();assert!(n::verify_raw_vector(&key,&hex(v["message"].as_str().unwrap()),&URL_SAFE_NO_PAD.encode(hex(v["signature"].as_str().unwrap()))).unwrap());}}
#[test]fn wycheproof_210_public_vectors_strict_profile(){let data:Value=serde_json::from_str(include_str!("vectors/wycheproof-ed25519.json")).unwrap();let mut count=0;for group in data["testGroups"].as_array().unwrap(){let p=hex(group["publicKey"]["pk"].as_str().unwrap());let mut valid_key=None;if let Ok(bytes)=<[u8;32]>::try_from(p.as_slice()){valid_key=n::signature::public_key(&URL_SAFE_NO_PAD.encode(&p),&n::hashes::key_id(&bytes)).ok();}for v in group["tests"].as_array().unwrap(){let got=valid_key.as_ref().and_then(|k|n::verify_raw_vector(k,&hex(v["msg"].as_str().unwrap()),&URL_SAFE_NO_PAD.encode(hex(v["sig"].as_str().unwrap()))).ok()).unwrap_or(false);assert_eq!(got,v["result"]=="valid","Wycheproof strict mismatch tcId {}",v["tcId"]);count+=1;}}assert_eq!(count,210);}
#[test]fn base64_padding_lengths_and_weak_keys(){for value in ["A","AA=","!",&"A".repeat(44)]{assert!(n::signature::decode::<32>(value).is_err());}for p in [[0;32],{let mut p=[0;32];p[0]=1;p}]{assert!(n::signature::public_key(&URL_SAFE_NO_PAD.encode(p),&n::hashes::key_id(&p)).is_err());}}
#[test]fn signature_count_exact_and_plus_one(){let list=|n| (0..n).map(|i|n::wire::SignatureRecord{protected:n::wire::Protected{protocol_version:1,algorithm:"Ed25519".into(),key_id:format!("key-{i:03}"),purpose:n::wire::Purpose::Package},value:"A".repeat(86)}).collect::<Vec<_>>();assert!(n::signature::signature_order(&list(MAX_SIGNATURES)).is_ok());assert_eq!(n::signature::signature_order(&list(MAX_SIGNATURES+1)).unwrap_err().code,"SIGNATURE_LIMIT");}
#[test]fn exact_decimal_precision_limits_and_no_monetary_float(){assert!(n::validation_2026::decimal(&format!("0.{}1","0".repeat(49)),50).is_ok());assert!(n::validation_2026::decimal(&format!("0.{}1","0".repeat(50)),50).is_err());for v in ["1e3","1,00","-1",".5","1.","NaN"]{assert!(n::validation_2026::decimal(v,50).is_err());}assert_eq!(n::validation_2026::cmp("0.1559","0.1502").unwrap(),std::cmp::Ordering::Greater);assert!(n::validation_2026::decimal(&"9".repeat(20),2).is_ok());assert!(n::validation_2026::decimal(&"9".repeat(21),2).is_err());}
#[test]fn calendar_and_instant_validation_no_implicit_clock(){for d in ["2026-02-29","2026-02-30","+026-01-01","0000-01-01"]{assert!(!n::time::civil(d));}assert!(n::time::civil("2028-02-29"));assert!(!n::time::instant("2026-01-01T+1:00:00Z"));assert_eq!(n::time::next("2026-01-31").unwrap(),"2026-02-01");}
#[test]fn host_document_byte_limits_exact_and_plus_one(){for max in [16384,65536,MAX_TRUST_BYTES]{let valid=format!("0{}"," ".repeat(max-1));assert!(n::strict_json::parse_with_limit(valid.as_bytes(),max).is_ok());assert_eq!(n::strict_json::parse_with_limit((valid+" ").as_bytes(),max).unwrap_err().code,"FILE_LIMIT");}}
#[test]fn candidate_owns_verified_bytes_and_metadata_after_input_changes(){
    let b:Value=serde_json::from_str(include_str!("../../../docs/evidence/5d3a/qa-example/bootstrap-public.json")).unwrap();let roots=serde_json::from_value::<Vec<n::wire::RootKey>>(b["rootKeys"].clone()).unwrap();
    let state=n::trust::TrustedState::qa_bootstrap(&roots).unwrap().propose_update(include_bytes!("../../../docs/evidence/5d3a/qa-example/trust.json"),"2026-10-23T12:00:00Z").unwrap();
    let mut input=include_bytes!("../../../docs/evidence/5d3a/qa-example/candidate.nomina-fiscal").to_vec();let original_hash=n::hashes::sha256(&input);
    let candidate=n::verify_candidate(&input,&state,&n::compatibility::CompiledPolicy::current_2026(),&n::revisions::MemoryRevisions::default(),n::wire::Capability::Inverse,"2026-10-23T12:00:00Z").unwrap();
    input.fill(0);assert_eq!(n::hashes::sha256(candidate.canonical_bytes()),original_hash);assert_eq!(candidate.report().identities.container_sha256,original_hash);assert_eq!(candidate.package().registry.exercise,2026);assert_eq!(candidate.report().execution,"not-installed-not-authorized");
    let identity:Value=serde_json::from_str(include_str!("../../../src/features/storage/build-identity.json")).unwrap();assert_eq!(candidate.report().identities.motor_identity,identity["engineVersion"].as_str().unwrap());
}
